package com.studenttong.mobile;
import android.app.*;import android.content.*;import android.location.*;import android.os.*;import org.json.*;import java.util.*;
public final class LocationModeManager {
 public static JSONObject runtime(Context c){try(Store s=new Store(c)){return new JSONObject(s.setting("_global","location.runtime","{}"));}catch(Exception e){return new JSONObject();}}
 public static boolean serviceAlive(Context c){try{ActivityManager m=(ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE);for(ActivityManager.RunningServiceInfo r:m.getRunningServices(100))if(r.service.getClassName().equals(MockLocationService.class.getName()))return true;}catch(Exception ignored){}return false;}
 public static void recoverInterrupted(Context c){JSONObject j=runtime(c);if(serviceAlive(c)||(!j.optBoolean("registered")&&!j.optString("state").equals("paused"))||System.currentTimeMillis()-j.optLong("updated")<5000)return;String p=j.optString("provider");if(!p.matches("studenttong_[a-f0-9]{32}"))return;try(Store s=new Store(c)){LocationManager m=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);if(j.optBoolean("registered")&&m.getAllProviders().contains(p))m.removeTestProvider(p);j.put("registered",false).put("state","stopped").put("message","上次模拟服务中断，已清理本模块Provider，未自动恢复模拟").put("updated",System.currentTimeMillis());s.setSetting("_global","location.runtime",j.toString());try{String aid=j.optString("aid");JSONObject config=new JSONObject(s.setting(aid,"location.lastMockConfig","{}"));JSONObject record=new JSONObject().put("id",j.optString("session")).put("before",config.optJSONObject("before")).put("selected",config.optJSONObject("point")).put("started",j.optLong("started")).put("ended",System.currentTimeMillis()).put("reason",config.optString("reason")).put("accuracy",config.optJSONObject("point")==null?0:config.optJSONObject("point").optDouble("accuracy")).put("state","interrupted").put("message","服务中断后已清理本模块Provider");new LocationHistoryManager(s,aid).add("corrections",record);}catch(Exception ignored){}}catch(Exception e){try(Store s=new Store(c)){j.put("state","error").put("message","上次服务中断且清理未确认，请重新授权后停止清理");s.setSetting("_global","location.runtime",j.toString());}catch(Exception ignored){}}}
 public static boolean isMock(Location l){return l!=null&&(Build.VERSION.SDK_INT>=31?l.isMock():l.isFromMockProvider());}
 public static boolean authorized(Context c){try{AppOpsManager m=(AppOpsManager)c.getSystemService(Context.APP_OPS_SERVICE);return m.checkOpNoThrow(AppOpsManager.OPSTR_MOCK_LOCATION,android.os.Process.myUid(),c.getPackageName())==AppOpsManager.MODE_ALLOWED;}catch(Exception e){return false;}}
 public static boolean active(Context c,String aid){JSONObject j=runtime(c);long age=SystemClock.elapsedRealtime()-j.optLong("heartbeatElapsed",-99999);return serviceAlive(c)&&aid.equals(j.optString("aid"))&&Arrays.asList("running","starting").contains(j.optString("state"))&&age>=0&&age<Math.max(15000,j.optLong("interval",2000)+5000);}
 public static boolean accepts(Context c,String aid,Location l){if(l==null)return false;if(!isMock(l))return !active(c,aid);JSONObject j=runtime(c);return active(c,aid)&&j.optString("provider").equals(l.getProvider());}
 public static String source(Location l){return l==null?"暂无定位":isMock(l)?"系统模拟定位":LocationManager.GPS_PROVIDER.equals(l.getProvider())?"GPS 真实定位":"网络定位";}
 public static JSONObject fix(Location l)throws Exception{return new JSONObject().put("latitude",l.getLatitude()).put("longitude",l.getLongitude()).put("accuracy",l.getAccuracy()).put("provider",l.getProvider()).put("time",l.getTime()).put("elapsed",l.getElapsedRealtimeNanos()).put("isMock",isMock(l)).put("crs","WGS84");}
 public static String label(Context c,String aid){JSONObject j=runtime(c);if(!j.has("aid"))return "正常定位";if(!aid.equals(j.optString("aid")))return Arrays.asList("running","starting","paused").contains(j.optString("state"))?"其他账号正在管理系统模拟定位":"正常定位";String state=j.optString("state");if(Arrays.asList("running","starting").contains(state)&&!active(c,aid))return "上次模拟定位已中断 · 请核对并清理";return state.equals("running")?"模拟定位已开启":state.equals("starting")?"正在等待系统定位回读":state.equals("paused")?"已暂停 · 使用正常定位":state.equals("error")?"模拟定位异常":state.equals("stopped")?"已停止 · 正常定位":"正常定位";}
}
